import { describe, expect, it } from 'vitest';
import { Session } from '../src/engine/interpreter';

/*
 * The coefficient commands as native LAMMPS reads them (src/input.cpp Input::pair_coeff, bond_coeff and friends, the
 * styles' coeff functions, utils::bounds and utils::numeric at b332f28): the box and style checks, the type ranges
 * ("Invalid range string", "Numeric index ... is out of bounds"), the count check of each style ("Incorrect args for
 * pair coefficients"; a few styles have their own wording) and the number checks. Measured with native LAMMPS
 * (/home/roy/.local/bin/lmp, b332f28): each row is an input; the expected error is the first line of native's message
 * (null when the input runs) and the values are the lines print wrote that start with VAL, joined by spaces. Not
 * compared here: pair table with its file missing and pair python (not in the native binary).
 */

const outcome = async (input: string): Promise<{ error: string | null; vals: string }> => {
  const vals: string[] = [];
  const s = new Session({
    emit: (ev: { kind: string; text?: string }) => { if (ev.kind === 'log' && ev.text?.startsWith('VAL ')) vals.push(ev.text); },
    writeFile: () => {},
  } as never);
  let error: string | null = null;
  // the engine's message starts with the line of the input ("line N: "), which native prints elsewhere
  try { await s.execute(input); } catch (e) { error = (e as Error).message.split('\n')[0].replace(/^line \d+: /, ''); }
  return { error, vals: vals.join(' ') };
};

